<?php if (!empty($tour['destinations'])): ?><section class="tour-destinations"><h2>ประเทศและเส้นทาง</h2><div class="tour-country-list"><?php foreach ($tour['countries'] as $country): ?><a href="<?= e(destination_url(['kind'=>'country','slug'=>$country['slug']])) ?>" class="card-destination"><?php if ($country['flag']): ?><img class="country-flag" src="<?= e((base_url() . ($country['flag']))) ?>" alt="ธง<?= e($country['name']) ?>" width="24" height="18"><?php endif ?><?= e($country['name']) ?></a><?php endforeach ?></div><ol class="tour-route-list"><?php foreach ($tour['destinations'] as $place): ?><li><a href="<?= e(destination_url($place)) ?>"><?= e($place['name']) ?></a><small><a href="<?= e(destination_url(['kind'=>'zone','slug'=>$place['zone_slug']])) ?>"><?= e($place['zone_name']) ?></a> / <a href="<?= e(destination_url(['kind'=>'country','slug'=>$place['country_slug']])) ?>"><?= e($place['country_name']) ?></a></small></li><?php endforeach ?></ol></section><?php endif ?>
